SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS activity_logs, booking_passengers, bookings, trips, umrah_requests, umrah_programs, service_requests, services, customers, branches, companies, cities, role_permissions, permissions, users, roles, settings;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_key VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE permissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, permission_key VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE role_permissions (role_id BIGINT UNSIGNED NOT NULL, permission_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id BIGINT UNSIGNED NOT NULL, branch_id BIGINT UNSIGNED NULL, company_id BIGINT UNSIGNED NULL, name VARCHAR(160) NOT NULL, username VARCHAR(100) NOT NULL UNIQUE, email VARCHAR(190) NULL UNIQUE, phone VARCHAR(30) NULL, password_hash VARCHAR(255) NOT NULL, status ENUM('active','disabled') NOT NULL DEFAULT 'active', last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, country_code CHAR(2) NOT NULL, name_ar VARCHAR(120) NOT NULL, name_en VARCHAR(120) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, UNIQUE KEY uq_city(country_code,name_ar)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE companies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, company_type ENUM('transport','agent') NOT NULL DEFAULT 'transport', logo_path VARCHAR(255) NULL, cover_path VARCHAR(255) NULL, description TEXT NULL, phone VARCHAR(30) NULL, whatsapp VARCHAR(30) NULL, status ENUM('active','hidden','suspended') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE branches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NULL, name VARCHAR(160) NOT NULL, city_id BIGINT UNSIGNED NULL, address VARCHAR(255) NULL, phone VARCHAR(30) NULL, status ENUM('active','disabled') DEFAULT 'active', FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL, FOREIGN KEY(city_id) REFERENCES cities(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
ALTER TABLE users ADD CONSTRAINT fk_users_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, ADD CONSTRAINT fk_users_company FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE SET NULL;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(160) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(190) NULL, nationality VARCHAR(100) NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_customer_phone(phone)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE trips (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, origin_city_id BIGINT UNSIGNED NOT NULL, destination_city_id BIGINT UNSIGNED NOT NULL, departure_at DATETIME NOT NULL, arrival_at DATETIME NULL, vehicle_type VARCHAR(100) NULL, vehicle_description TEXT NULL, price DECIMAL(12,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'SAR', seats_total SMALLINT UNSIGNED NOT NULL, status ENUM('available','full','paused','cancelled','completed') NOT NULL DEFAULT 'available', is_published TINYINT(1) NOT NULL DEFAULT 1, details TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id), FOREIGN KEY(origin_city_id) REFERENCES cities(id), FOREIGN KEY(destination_city_id) REFERENCES cities(id), FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_trip_search(departure_at,status,is_published)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference_code VARCHAR(24) NOT NULL UNIQUE, trip_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, passengers_count SMALLINT UNSIGNED NOT NULL, status ENUM('new','reviewing','confirmed','rejected','cancelled') NOT NULL DEFAULT 'new', customer_notes TEXT NULL, internal_notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(trip_id) REFERENCES trips(id), FOREIGN KEY(customer_id) REFERENCES customers(id), INDEX idx_booking_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE booking_passengers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_id BIGINT UNSIGNED NOT NULL, full_name VARCHAR(160) NOT NULL, document_ref VARCHAR(100) NULL, FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE umrah_programs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, description TEXT NULL, duration_days SMALLINT UNSIGNED NULL, departure_at DATETIME NULL, price DECIMAL(12,2) NULL, currency CHAR(3) DEFAULT 'SAR', seats_total SMALLINT UNSIGNED NULL, included_services TEXT NULL, image_path VARCHAR(255) NULL, status ENUM('active','hidden','full') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE umrah_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference_code VARCHAR(24) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, program_id BIGINT UNSIGNED NULL, people_count SMALLINT UNSIGNED NOT NULL, city VARCHAR(120) NULL, expected_date DATE NULL, service_type VARCHAR(120) NULL, notes TEXT NULL, status ENUM('new','reviewing','quoted','confirmed','rejected','cancelled') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(program_id) REFERENCES umrah_programs(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE services (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, service_type ENUM('visa','visit','other') NOT NULL, description TEXT NULL, requirements TEXT NULL, price DECIMAL(12,2) NULL, currency CHAR(3) DEFAULT 'SAR', processing_days VARCHAR(80) NULL, image_path VARCHAR(255) NULL, status ENUM('active','hidden') DEFAULT 'active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE service_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference_code VARCHAR(24) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, service_id BIGINT UNSIGNED NOT NULL, nationality VARCHAR(100) NULL, people_count SMALLINT UNSIGNED DEFAULT 1, details TEXT NULL, attachment_path VARCHAR(255) NULL, status ENUM('new','reviewing','need_info','quoted','completed','rejected','cancelled') DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, action_key VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NULL, entity_id BIGINT UNSIGNED NULL, description TEXT NULL, ip_address VARCHAR(45) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_activity_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO roles(role_key,name) VALUES ('super_admin','مدير النظام الرئيسي'),('admin_staff','موظف الإدارة'),('company_manager','مسؤول شركة نقل'),('booking_agent','موظف الحجوزات'),('umrah_agent','موظف العمرة'),('visa_agent','موظف التأشيرات');
